Given an integer array arr[] and an integer k, determine whether there exist two indices i and j such that arr[i] == arr[j] and |i - j| ≤ k. If such a pair exists, return 'Yes', otherwise return 'No'.Examples: Input: k = 3, arr[] = [1, 2, 3, 4, 1, 2, 3, 4]Output: NoExplanation: Each element in the given array arr[] appears twice and the distance between every element and its duplicate is 4.Input: k = 3, arr[] = [1, 2, 3, 1, 4, 5]Output: YesExplanation: 1 is present at index 0 and 3.Input: k = 3, arr[] = [1, 2, 3, 4, 5]Output: NoExplanation: There is no duplicate element in arr[].Try It Yourself[Naive Approach] - O(n * k) Time and O(1) SpaceThe idea is to run two loops. The outer loop picks every index i as a starting index, and the inner loop compares all elements which are within k distance of i, i.e. i + k.Below is given the implementation:
            C++

    #include <bits/stdc++.h>
using namespace std;

bool checkDuplicatesWithinK(vector<int> &arr, int k)
{
    int n = arr.size();

    // Traverse for every element
    for (int i = 0; i < n; i++) {

        // Traverse next k elements 
        for (int c = 1; c <= k && (i + c) < n; c++) {
            int j = i + c;

            // If we find one more occurrence 
            // within k
            if (arr[i] == arr[j])
              return true;
        }
    }
    return false;
}

// Driver method to test above method
int main()
{
    vector<int> arr = {10, 5, 3, 4, 3, 5, 6};
    if (checkDuplicatesWithinK(arr, 3))
        cout << "Yes";
    else
        cout << "No";
    return 0;
}


